import { DEFAULT_SCRIPT_FONTS, GROUPING_DEFAULTS_BY_SCRIPT, NO_SPACE_SCRIPTS, RTL_SCRIPTS, WritingScript } from "./caption-style-v2";

/**
 * Caption languages (captions v2, Phase 8): the ONE list the server (CAPTION_TARGET_LANGUAGES), the AI Director and
 * the phone (apps/social-studio-mobile/lib/features/studio/caption_languages_data.dart, generated by
 * packages/video-contracts/scripts/gen-caption-languages-dart.ts) read. Edit this file, then run
 * `npx tsx packages/video-contracts/scripts/gen-caption-languages-dart.ts`; a test fails when the Dart copy is stale.
 */

export interface CaptionLanguage {
  /** BCP-47 tag (hi-Latn = Hindi in Roman letters / Hinglish; zh-Hans / zh-Hant = Simplified / Traditional Chinese). */
  code: string;
  /** English name shown in the app and used in translation prompts. */
  name: string;
  nativeName: string;
  /**
   * Language code sent to the speech-to-text provider (Whisper: ISO-639-1, see
   * apps/180-social-studio-backend/src/api/v1/media-editor/media-transcription.ts normalizeRequestLanguage).
   * null = the provider does not list the language; the app sends "auto" (detection) instead.
   */
  transcriptionCode: string | null;
  script: WritingScript;
  /** Font families in fallback order (Google Fonts, SIL OFL). */
  fontStack: string[];
  maxCharsPerLine: number;
  maxCharsPerSecond: number;
  rtl: boolean;
  /** Words are written without spaces (CJK, Thai): never joined with " ". */
  noSpaces: boolean;
  /** The script has upper/lower case; casing rules use `casingLocale` (Turkish: i → İ). */
  hasCase: boolean;
  casingLocale: string | null;
  /** How a translation into this language is asked for: hi-Latn is Hindi written in Roman letters. */
  translateAs: { language: string; script: "native" | "roman" };
  /** Other codes that resolve to this language (old projects, provider-reported codes). */
  aliases: string[];
}

type Seed = {
  code: string;
  name: string;
  nativeName: string;
  stt: string | null;
  script: WritingScript;
  fonts?: string[];
  locale?: string;
  translateAs?: { language: string; script: "native" | "roman" };
  aliases?: string[];
};

const SEEDS: Seed[] = [
  { code: "en", name: "English", nativeName: "English", stt: "en", script: "latin" },
  { code: "hi", name: "Hindi", nativeName: "हिन्दी", stt: "hi", script: "devanagari" },
  // Whisper has no Hinglish: "hi" is sent and the transcript usually comes back in Devanagari; captions are then
  // converted to Roman letters (translateAs).
  { code: "hi-Latn", name: "Hinglish (Roman)", nativeName: "Hinglish", stt: "hi", script: "latin", locale: "en", translateAs: { language: "hi", script: "roman" } },
  { code: "bn", name: "Bengali", nativeName: "বাংলা", stt: "bn", script: "bengali" },
  { code: "ta", name: "Tamil", nativeName: "தமிழ்", stt: "ta", script: "tamil" },
  { code: "te", name: "Telugu", nativeName: "తెలుగు", stt: "te", script: "telugu" },
  { code: "mr", name: "Marathi", nativeName: "मराठी", stt: "mr", script: "devanagari" },
  { code: "gu", name: "Gujarati", nativeName: "ગુજરાતી", stt: "gu", script: "gujarati" },
  { code: "kn", name: "Kannada", nativeName: "ಕನ್ನಡ", stt: "kn", script: "kannada" },
  { code: "ml", name: "Malayalam", nativeName: "മലയാളം", stt: "ml", script: "malayalam" },
  { code: "pa", name: "Punjabi", nativeName: "ਪੰਜਾਬੀ", stt: "pa", script: "gurmukhi" },
  // Odia is not in Whisper's language list: detection is used.
  { code: "or", name: "Odia", nativeName: "ଓଡ଼ିଆ", stt: null, script: "odia" },
  { code: "as", name: "Assamese", nativeName: "অসমীয়া", stt: "as", script: "bengali" },
  { code: "ur", name: "Urdu", nativeName: "اردو", stt: "ur", script: "arabic", fonts: ["Noto Nastaliq Urdu", "Noto Sans Arabic", "Noto Sans"] },
  { code: "ne", name: "Nepali", nativeName: "नेपाली", stt: "ne", script: "devanagari" },
  { code: "sd", name: "Sindhi", nativeName: "سنڌي", stt: "sd", script: "arabic" },
  { code: "ar", name: "Arabic", nativeName: "العربية", stt: "ar", script: "arabic" },
  { code: "fa", name: "Persian", nativeName: "فارسی", stt: "fa", script: "arabic" },
  { code: "es", name: "Spanish", nativeName: "Español", stt: "es", script: "latin" },
  { code: "pt", name: "Portuguese", nativeName: "Português", stt: "pt", script: "latin" },
  { code: "fr", name: "French", nativeName: "Français", stt: "fr", script: "latin" },
  { code: "de", name: "German", nativeName: "Deutsch", stt: "de", script: "latin" },
  { code: "it", name: "Italian", nativeName: "Italiano", stt: "it", script: "latin" },
  { code: "id", name: "Indonesian", nativeName: "Bahasa Indonesia", stt: "id", script: "latin" },
  { code: "ms", name: "Malay", nativeName: "Bahasa Melayu", stt: "ms", script: "latin" },
  { code: "tr", name: "Turkish", nativeName: "Türkçe", stt: "tr", script: "latin", locale: "tr" },
  { code: "ru", name: "Russian", nativeName: "Русский", stt: "ru", script: "cyrillic" },
  { code: "uk", name: "Ukrainian", nativeName: "Українська", stt: "uk", script: "cyrillic" },
  { code: "vi", name: "Vietnamese", nativeName: "Tiếng Việt", stt: "vi", script: "latin" },
  { code: "th", name: "Thai", nativeName: "ไทย", stt: "th", script: "thai" },
  { code: "ja", name: "Japanese", nativeName: "日本語", stt: "ja", script: "cjk-jp" },
  { code: "ko", name: "Korean", nativeName: "한국어", stt: "ko", script: "korean" },
  // Whisper takes one "zh"; whether it writes Simplified or Traditional characters is not guaranteed.
  { code: "zh-Hans", name: "Chinese (Simplified)", nativeName: "简体中文", stt: "zh", script: "cjk-sc", aliases: ["zh"] },
  { code: "zh-Hant", name: "Chinese (Traditional)", nativeName: "繁體中文", stt: "zh", script: "cjk-sc", fonts: ["Noto Sans TC", "Noto Sans SC", "Noto Sans"] },
  // Whisper calls Filipino "tagalog" (tl).
  { code: "fil", name: "Filipino", nativeName: "Filipino", stt: "tl", script: "latin", aliases: ["tl"] },
  { code: "sw", name: "Swahili", nativeName: "Kiswahili", stt: "sw", script: "latin" },
];

const CASED: ReadonlySet<WritingScript> = new Set(["latin", "cyrillic"]);

export const CAPTION_LANGUAGES: readonly CaptionLanguage[] = SEEDS.map((s) => {
  const d = GROUPING_DEFAULTS_BY_SCRIPT[s.script];
  const hasCase = CASED.has(s.script);
  return {
    code: s.code,
    name: s.name,
    nativeName: s.nativeName,
    transcriptionCode: s.stt,
    script: s.script,
    fontStack: s.fonts ?? [DEFAULT_SCRIPT_FONTS[s.script], "Noto Sans"],
    maxCharsPerLine: d.maxCharsPerLine,
    maxCharsPerSecond: d.maxCharsPerSecond,
    rtl: RTL_SCRIPTS.has(s.script),
    noSpaces: NO_SPACE_SCRIPTS.has(s.script),
    hasCase,
    casingLocale: hasCase ? (s.locale ?? s.code.split("-")[0]) : null,
    translateAs: s.translateAs ?? { language: s.code, script: "native" },
    aliases: s.aliases ?? [],
  };
});

/** A language by code or alias, case-insensitive ("ZH-HANS", "zh", "tl"); undefined when unknown. */
export function findCaptionLanguage(code: string | null | undefined): CaptionLanguage | undefined {
  const c = (code ?? "").trim().toLowerCase();
  if (!c) return undefined;
  return CAPTION_LANGUAGES.find((l) => l.code.toLowerCase() === c || l.aliases.includes(c));
}
